mapper.sql:
WHERE deleted = false

    AND state = #{req.state}


    AND pwd_reset_required = #{req.pwdResetRequired}


    AND EXISTS (
        SELECT 1 FROM sys_user_role ur
        WHERE ur.user_id = sys_user.user_id AND ur.role_id = #{req.roleId}
    )


    AND (username ILIKE CONCAT('%', #{req.keyword}, '%')
         OR nickname ILIKE CONCAT('%', #{req.keyword}, '%')
         OR email ILIKE CONCAT('%', #{req.keyword}, '%'))
